WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (499::BIGINT, 'Si usted es repitente puede ser que le sirva, pero si es por primera vez le va a costar demasiado, hace las clases largas y aveces le gusta dar demasiada teoría respecto a los temas como con GeoGebra, hay otras mejores opciones de profe.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Aspectos de calificación claros', 'Exámenes retadores']::TEXT[], '2025-12-06T00:00:00+00:00'::TIMESTAMPTZ, '3000f07454a04f41799cee708a030b6e119d6fc0b76d85ef4b6c17bad17cd45a'::TEXT, ARRAY[605]::BIGINT[]),
    (499::BIGINT, 'Para llevar CDI por primera vez con él no lo recomiendo. Explica de más en cuanto a "el origen de las fórmulas" y en general no es muy atento en que el estudiante entienda. Sin embargo, califica normal o inclusive chill y no es tan exigente, diría yo que es un profe bueno si ya llevaste el curso.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2025-12-03T00:00:00+00:00'::TIMESTAMPTZ, '41eb3c43ae98965a500acc03365f9befcb21d8c11b0aae2014c44137e0964ed1'::TEXT, ARRAY[605]::BIGINT[]),
    (499::BIGINT, 'Hay que ser autodidacta, increíble que de 2 clases a la semana solo da 1, solo dice que la segunda va a ser para que nosotros nos pongamos al día con lo que falta de la semana, no tiene presentaciones son documentos que parecen word. Hay quiz virtual todas las semanas, pasé por ir de oyente con otro'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas']::TEXT[], '2025-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'e49e0097408401cb8406500c81537a704007392bdf741d1027f6b0e0798debd8'::TEXT, ARRAY[935]::BIGINT[]),
    (499::BIGINT, 'Matriculé con el si es autodidacta, sino ni lo piense. Deja quices virtuales todas las semanas. Las clases sinceramente son malas, no es muy bueno. Claro que siempre está atento a las necesidades de uno y si va a consulta le ayuda. Ecuas es fácil en general, entonces el profe funciona para pasar.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-06-19T00:00:00+00:00'::TIMESTAMPTZ, '279a0cd1b7adde644c06b278300b2b4049bcd26184bd349b3950911714b6628b'::TEXT, ARRAY[935]::BIGINT[]),
    (499::BIGINT, 'Si tiene la oportunidad de llevar con Greivin, no dude en llevarlo con otra persona, no explica bien, hace ejercicios bastante mediocres, no ayuda a entender, los quices súper difíciles a comparación de lo visto en clase.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2025-02-13T00:00:00+00:00'::TIMESTAMPTZ, '135f7b7b1fe76d7cf33fc2708bfc2131c6e1cd00eba2487fcc04a4da4b65f895'::TEXT, ARRAY[605]::BIGINT[]),
    (499::BIGINT, 'Explica super bien, las clases son rápidas y organiza muy bien las clases, quizás suele calificar un poco duro la primera parte del curso pero al final lo compensó con actividades extra. Respetuoso y va a lo que va, profe serio pero siempre dispuesto a ayudar en lo que le pregunten.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2025-02-05T00:00:00+00:00'::TIMESTAMPTZ, '15d010a5f6fa3a7629d159a0465661bcaca16bfbdf2fe347a01f7787fd0398dd'::TEXT, ARRAY[935]::BIGINT[]),
    (499::BIGINT, 'Muy buen profesor, a pesar de que estuvo solo 1 mes, logró explicar todo de manera clara. Lo gracioso es que escribe y escribe y parece no cansarse, llena las pizarras en un santiamén. Pero es mera teoría o demostración de las fórmulas. Es buena persona y da buena retroalimentación.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-09-04T00:00:00+00:00'::TIMESTAMPTZ, 'c460ea1d0755f2e7dcdf95ba6084eeb6c5e26cade6df7da881bf5d3a7918d347'::TEXT, ARRAY[935]::BIGINT[]),
    (499::BIGINT, 'Es demasiado desordenado explicando, sus clases se hacen pesadas y pierde mucho tiempo con ejemplos que no sirven para nada, también los quices son complicados, una vez nos puso uno super difícil apenas después del parcial.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2024-07-20T00:00:00+00:00'::TIMESTAMPTZ, '0e7be88a192ea4d86ed99e382e0b3372b458918480473bcb2384a926d57d5d4e'::TEXT, ARRAY[605]::BIGINT[]),
    (499::BIGINT, 'Si tienen la oportunidad de llevarlo con otra persona, no lo duden, el califica súper duro y si en los exámenes no ve el procedimiento que él quiere, le pone todo malo, aunque tenga la respuesta correcta, las clases súper largas no da recesos además de que no lleva apoyo, todo lo desordena.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Clases largas']::TEXT[], '2024-06-26T00:00:00+00:00'::TIMESTAMPTZ, '1fe1196ffeef1ddce72b9a9dc5fb09255d4752ae3c34baac73c6ac84624c0b67'::TEXT, ARRAY[605]::BIGINT[]),
    (499::BIGINT, 'No es un buen profesor, es muy desordenado en pizarra, no da recesos y sus clases son demasiado pesadas, no lleva ningún apoyo audiovisual más que el pdf que brinda la cátedra y gráficas que no son de mucha ayuda. Parece que improvisa que materia ver y sus quices son complejos.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Clases largas']::TEXT[], '2024-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'e769b4c95f346869360b8719a2b00b36a467bb4f6e2111bf1fb238a8dce3da64'::TEXT, ARRAY[605]::BIGINT[]),
    (499::BIGINT, 'Siento que los ejercicios realizados en clase son muy simples, verdaderamente nunca revisé los apuntes de clase ya que en realidad no eran de mucha ayuda. Si bien a veces deja tareas para ayudar con el porcentaje y eso se agradece, mi aprendizaje de este curso fue por estudiar con catedra.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2024-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'a933fd8e90e7b368123d3c84ffdab89c3318e926e8bf517516b82d980cc5f4e4'::TEXT, ARRAY[605]::BIGINT[]),
    (499::BIGINT, 'Es importante considerar la modalidad, al ser virtual es un poco más autodidacta, sin embargo, hay bastante material disponible, las clases virtuales quedan grabadas y las asincrónicas se basan en material de la cátedra. Se hacen quices semanales.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'fb83422777ed2ae13d7b325db603b87894dd9bec67e06606f5f648c7736a787f'::TEXT, ARRAY[935]::BIGINT[]),
    (499::BIGINT, 'Las clases en virtual pueden ser un poco rápidas. Este semestre tomó la modalidad de una clase virtual y la otra asincrónica a la semana, en la que se hace un quiz (sencillo), para el cual hay que ver la mitad de la materia que entra en base a la cátedra. Pero buen profe y buenas clases.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'f297c1f40b2dbf3e0d937300116d602cb37902841b9017477faba334f7ce2395'::TEXT, ARRAY[935]::BIGINT[]),
    (499::BIGINT, 'El profe es buena gente, quiere ayudar y deja algunas prácticas y evaluaciones para hacer en la casa, pero muchas veces se enreda con las explicaciones, se complica mucho y la mayoría de las clases son resolviendo ejemplos no tan complicados. Los quices son bastante dificiles.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'eaeaa4c90ad5ac055fee55cfa362e3a1b16dea2be24e8a74b29b62955c8f0e57'::TEXT, ARRAY[605]::BIGINT[]),
    (499::BIGINT, 'El curso de manera virtual permite que el estudiante estudie todo por su cuenta (lo cual puede ser bueno dependiendo de cada uno), además deja quizzes muy sencillos pero que sirven para reforzar concepto. Si no es autodidacta, no lo lleve virtual, ya que es la gracia de la modalidad.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos exámenes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-14T00:00:00+00:00'::TIMESTAMPTZ, '0f6a7c0bf01c3e84135f857e690d2f881200ed08e17ebf40d603036b096fec12'::TEXT, ARRAY[935]::BIGINT[]),
    (499::BIGINT, 'El profe explica de manera clara, tiene mucho material de apoyo y practicas extra lo cual es de suma ayuda. Y siempre esta dispuesto a aclarar dudas'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2024-01-15T00:00:00+00:00'::TIMESTAMPTZ, '2ee0272d8380d7078548bce8c214ac1ee47f22b092ee37a2e0962a03dda6bb10'::TEXT, ARRAY[935]::BIGINT[]),
    (499::BIGINT, 'no es mala nota, pero no explica para nada bien'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2023-10-08T00:00:00+00:00'::TIMESTAMPTZ, '0bcdc596609b2bbb47634f8dea55003698cfb677b8799e91934415bd9f9a7376'::TEXT, ARRAY[605]::BIGINT[]),
    (499::BIGINT, 'Muy buen profe, explica genial y las tareas dejan bastante claro lo que el espera que uno aprenda. Los exámenes que hace son simples, pero si no estudió está listo, sépalo, porque son medio teóricos. Recomendado 100%.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-23T00:00:00+00:00'::TIMESTAMPTZ, '4f89a62213d6052d534ba743245e9b8fafbb74a865e286ce3fbf5c50d8173fc1'::TEXT, ARRAY[103]::BIGINT[]),
    (499::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-02-06T00:00:00+00:00'::TIMESTAMPTZ, '7bbd67b48d365c46a2df612e6ede1ae17cac7289ab124db178b09419587c0797'::TEXT, ARRAY[935]::BIGINT[]),
    (499::BIGINT, 'Ecua es un curso bastante pasable. El profe explica bien y si uno no se puede conectar a la clase, basta con hacer las consignas de la catedra porque son demasiado buenas. Para los examenes estudie con la practica del GAAP y fijo pasa.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, 'dedd88f0e11c3788e01e61b8e602d94f24402b7ae118a6819ebe293965bd47c6'::TEXT, ARRAY[935]::BIGINT[]),
    (499::BIGINT, 'Explica muy bien la materia, en modalidad virtual da la clase completa, pero, solo una a la semana. En consulta ayuda mucho y en general, lo recomiendo.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-26T00:00:00+00:00'::TIMESTAMPTZ, 'ba93013250f0769149b13950f66d03d57536d5238778c488625b6d0d610696ae'::TEXT, ARRAY[935]::BIGINT[]),
    (499::BIGINT, 'Durante las clases presenciales me pareció un muy buen profesor, sin embargo, las clases virtuales fueron un poco aburridas. Lo bueno es que comparte el material de otros profesores para reforzar el estudio.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, 'a3f61e40aeee6b548ab9b3b1f877b267800c23ef9a1a3ebf803264ad97a58e20'::TEXT, ARRAY[103]::BIGINT[]),
    (499::BIGINT, 'Es demasiado duro, si pudiera evitarlo en futuros cursos lo haría. Eso sí, las clases virtuales me han gustado porque puedo repetir la clase y entiendo mejor. Es demasiado desordenado en la pizarra.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2020-06-05T00:00:00+00:00'::TIMESTAMPTZ, '03db888158c1f7b9a15c57d0e791a16209909df8547d3f94f6d72f9ebeecb1ec'::TEXT, ARRAY[935]::BIGINT[]),
    (499::BIGINT, 'Muy recomendado, excelente profesor, los ejemplos y ejercicios de quices y tareas son muy parecidos a los del examen. Dispuesto ayudar. Muy respetuoso.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2020-02-05T00:00:00+00:00'::TIMESTAMPTZ, '9c158ed88138a15fd5d8359d74dacb3e76ec799efc16883588ae204b2bbd2b89'::TEXT, ARRAY[605]::BIGINT[]),
    (499::BIGINT, 'Muy buen profe, explica muy bien y es muy agradable. Nos deja algunas tareas y quizes relativamente seguido.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-11T00:00:00+00:00'::TIMESTAMPTZ, '8878855678b730ff109773aa5873e6232a3ecf99e2b8dcedd982c1916b75c55a'::TEXT, ARRAY[605]::BIGINT[]),
    (499::BIGINT, 'Se hace 3 quices por examen, el profe explica bien la materia. En sí la materia del curso no es difícil.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2019-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'ef31a6740b035dae416ddf09370e561015084ed67b3913e09843fc675d868970'::TEXT, ARRAY[935]::BIGINT[]),
    (499::BIGINT, 'Greivin es super buen profe. Las clases son faciles de entender a pesar de que va un poco rápido. Califica super bien y devuelve el examen rapidísimo. Clases ligeras y sencillas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-21T00:00:00+00:00'::TIMESTAMPTZ, '46925335c19275dd45566c172dc9bbe540a87534175bcb50457cdd7a5dc45f41'::TEXT, ARRAY[935]::BIGINT[]),
    (499::BIGINT, 'las clases son muy densas y aburridas pero el profe es muy responsable y buena persona, aparte el curso es facil'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-19T00:00:00+00:00'::TIMESTAMPTZ, '12ebc1afd113d821c7f9dd5bf36bd35b2c4cacea41fa6198e6c56d0341fea19c'::TEXT, ARRAY[935]::BIGINT[]),
    (499::BIGINT, 'Es ordenado dando la clase, lleva ejemplos de la materia, es justo calificando los exámenes'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'b7650fa99663ff42efdfb667b35b7546d069e45ef59ba801bd3e9fa95aec81e6'::TEXT, ARRAY[935]::BIGINT[]),
    (499::BIGINT, 'El profe es excelente, la materia la explica muy clara y de manera ordenada, califica bien y revisa rápido las evaluaciones. Las clases se vuelven largas, pero es por la materia que se ve.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2019-06-12T00:00:00+00:00'::TIMESTAMPTZ, '37a36957d62be62bbce6f60515b40d730005afbd90e7d0bb2093784fa1fab310'::TEXT, ARRAY[935]::BIGINT[]),
    (499::BIGINT, 'Las clases más eternas que va llevar en su vida, sin joder. Pero este mae es un DIOS, el mae explica muy muy claro, y hace un pichaaazo de ejemplos, copie todo y llévelo al día y ya pasó. Califica normal y muy muy rápido. ¿Ya dije que las clases son largas?'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-12T00:00:00+00:00'::TIMESTAMPTZ, '828d19e3f18c59925db6e4183ecc637427d49c299326aef3606724210e0574be'::TEXT, ARRAY[935]::BIGINT[]),
    (499::BIGINT, 'El mae explica super bien y ayuda cuando le pide'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-05-26T00:00:00+00:00'::TIMESTAMPTZ, 'a8b0fadff2970d51b5dab987ce1f0cc30101a9b37306d88689cbed3921b47a88'::TEXT, ARRAY[935]::BIGINT[]),
    (499::BIGINT, 'Su clase en ocaciones se hace super pesada y larga, pero explica bastante bien. No califica duro y revisa exámenes rápido. Es muy buen profe.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2019-01-03T00:00:00+00:00'::TIMESTAMPTZ, 'a224b9799c2cffc92946ba82f94e6ee37f3714aa1351bfc5c05aa9091512713b'::TEXT, ARRAY[935]::BIGINT[]),
    (499::BIGINT, 'Mayoría de quices en pareja, califica muy justamente. Explica detalladamente pero la clase se vuelve un poco pesada.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-11T00:00:00+00:00'::TIMESTAMPTZ, '13543779638763b09b829a5f4895f291310734f2afe24dd1c2c2cd4acb7bfd7f'::TEXT, ARRAY[935]::BIGINT[]),
    (499::BIGINT, 'Explica muy bien; es un poco desordenado en la pizarra. Pocos quices y difíciles. En general, buen profe.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-03T00:00:00+00:00'::TIMESTAMPTZ, '88e0b343a712a2dcb52a58eaaabf9470727f03137dea984d854417323bef6594'::TEXT, ARRAY[935]::BIGINT[]),
    (499::BIGINT, 'El profe es un poco desordenado en la pizarra pero explica todo super bien y es bastante claro'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-24T00:00:00+00:00'::TIMESTAMPTZ, '0a9cf4e1cf6990df70ba3c0b0954d228d25a8c1906a760dda4615d0c361eeb8e'::TEXT, ARRAY[935]::BIGINT[]),
    (499::BIGINT, 'Sumamente desordenado en la pizarra, pero muy claro apra explicar, recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-30T00:00:00+00:00'::TIMESTAMPTZ, '0d8894df912f644d95e2ef8dd25fec7cb4577e9b5d1f58b36ea40fe717a8f52c'::TEXT, ARRAY[935]::BIGINT[]),
    (499::BIGINT, 'explica bastante bien y de donde salen las cosas y teoremas, califica suave y revisa muy rapido, en conclusion muy buen profe'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-18T00:00:00+00:00'::TIMESTAMPTZ, '4b4fb111bc89c40a9bcca19afab2dd384c221920d86717ac4fb1e211fb8a63d9'::TEXT, ARRAY[935]::BIGINT[]),
    (499::BIGINT, 'Al principio de cada tema habla mucho que no es muy relevante a lo evaluado, pero es excelente profe y explica muy bien. Se le hace un desmadre en la pizarra entonces hay que ir siguiéndolo, si no uno se pierde. Revisa rapidísimo; espere tener el examen la misma semana que lo hizo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-12-09T00:00:00+00:00'::TIMESTAMPTZ, '2b3d3cca0ce7882f883b3b648d1e29a4a4bd4c2852ddf99409a933ea3a255d93'::TEXT, ARRAY[935]::BIGINT[]),
    (499::BIGINT, 'Buen profe en general. Da la materia muy clara, ejemplo muy útiles para exámenes y a veces deja tareas en lugar de quices. Revisa los exámenes bastante rápido y califica justo.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-04T00:00:00+00:00'::TIMESTAMPTZ, 'df48973d6e6bbe044515fa4d300bf8099561ca438d1fe2f31440184db30cb4bb'::TEXT, ARRAY[935]::BIGINT[]),
    (499::BIGINT, 'El profe explica muy bien y califica muy suave. Lo unico malo es que es un poco desordenado. Recomendado'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'c43a32b67dd936bf3144db81778d8e456e7a2cd735710c65f59d1762115ba3ee'::TEXT, ARRAY[935]::BIGINT[]),
    (499::BIGINT, 'Este profe es excelente. Explica con mucha claridad y siempre va a tiempo con la materia. Revisa demasiado rápido por lo que a los dos días ya tiene los exámenes revisados. Hace más tareas que quices, a veces son un toque volados.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-11-29T00:00:00+00:00'::TIMESTAMPTZ, '1e5788f167d9281d805949019f1d7bd24f884b6a13a4902e35c251ee22b2a787'::TEXT, ARRAY[935]::BIGINT[]),
    (499::BIGINT, 'Explica bastante bien, califica muy justo. Las clases son un poco aburridas.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-25T00:00:00+00:00'::TIMESTAMPTZ, '1c255c917394dc20ff319f6ba5a5f2165357646a81a8c00ec6e96db595dafd23'::TEXT, ARRAY[935]::BIGINT[]),
    (499::BIGINT, 'Iba muy rápido, a veces escribía muy desmadre en la pizarra y nada de practica. Es buena gente pero la clase era demasiado aburrida.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-07-27T00:00:00+00:00'::TIMESTAMPTZ, '3236d47d2b49d3961140a6cc8f6fb521c2aa887742def416c3b97271ad001624'::TEXT, ARRAY[1041]::BIGINT[]),
    (499::BIGINT, 'Me gustaria concordar con el resto de calificaciones pero difiero. Explica muy mal, asì como de libro de texto y sin parar, tenìa que escoger entre copiar y entenderle, malo respondiendo dudas, ejemplos del folleto, no le da tiempo de hacer practica para el examen. Buena gente pero ABURRIDISIMO!'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-30T00:00:00+00:00'::TIMESTAMPTZ, '273b2fd470fc9af4291938d863b50ce2b1296f99db98ff0905fbf6317c66e306'::TEXT, ARRAY[1641, 1642]::BIGINT[]),
    (499::BIGINT, 'Clases monótonas, inicia con la materia desde el primer minuto de la lección y hasta el final. Pausas prácticamente inexistentes entre temas. ¿Práctica para examen en clase? Increíblemente poca.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'c75846c0ead2e23708ab7f8177f0b929a3404ee0b5786700c26f8c4a29c3be5c'::TEXT, ARRAY[1041]::BIGINT[]),
    (499::BIGINT, 'Muy bueno a explicar, le gusta dar esta materia, califica suave y se aprende bastante.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-12-11T00:00:00+00:00'::TIMESTAMPTZ, '61815d512c2b6d4f313558727fae28bdd16ea36a8cae9dbb04ce51b6189556ec'::TEXT, ARRAY[1041]::BIGINT[]),
    (499::BIGINT, 'Excelente profesor, explica muy bien y califica normal tirando a suave. De los mejores de la escuela.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-07-04T00:00:00+00:00'::TIMESTAMPTZ, '84a755275fe7ddde991defd474408447f0225c122bf8b7ee89f9a23d4df3a422'::TEXT, ARRAY[935]::BIGINT[]),
    (499::BIGINT, 'El profe va volando con la materia, sin embargo, se le entiende muy bien. Califica suave. Lo único que no hace es mucha práctica para examen.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-30T00:00:00+00:00'::TIMESTAMPTZ, '8fe1afb1c91f758c670437e5a8c067383e9f54b1fa9162c05868bcd3fd6f9329'::TEXT, ARRAY[1041]::BIGINT[]),
    (499::BIGINT, 'Muy buen profe, siempre esta para ayudar y no deja muchas tareas'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2016-06-28T00:00:00+00:00'::TIMESTAMPTZ, '566dcffdc625b604502f95763e86ab719b664f28e0b78d2ff96bf15ef455668d'::TEXT, ARRAY[1041]::BIGINT[]),
    (499::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Brinda apoyo']::TEXT[], '2016-06-27T00:00:00+00:00'::TIMESTAMPTZ, '0be6738adfe39dd3f20ae57d5112241cd28638746ef327c44b0bbb93957d97f3'::TEXT, ARRAY[935]::BIGINT[]),
    (499::BIGINT, '¡Muy buen profe! Domina la materia. Va rápido, pero tampoco un montón. ¡Explica bastante! Es buena gente, califica suave, es comprensivo, siempre anuente a ayudar, quices y tareas ayudan a estudiar (a veces los deja para la casa y en parejas). ¿Ya dije que explica bastante? xD ¡Recomendado!'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2016-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'a1e63c61ea371dd1d46780a1bc9fe277fab791834f02e5b15a8e8e730a1bcf16'::TEXT, ARRAY[1041]::BIGINT[]),
    (499::BIGINT, 'Ve la materia super rápido. Y lo que menos me gustó fue que no practica para nada. Siento que si sacará tiempo para practicar, volveria a llevar un curso con él. Hacía quices de la materia vista en clase, califica suave lo cual es bueno.'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'e00c55cb69531f8dcfc7b88f15110bb19253dd06d3357b59af43cb1569f3ec2c'::TEXT, ARRAY[1041]::BIGINT[]),
    (499::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-24T00:00:00+00:00'::TIMESTAMPTZ, '34f428016f88cde5538ac0a1db1791555b73636f1e3591829b6f123037bda19a'::TEXT, ARRAY[1041]::BIGINT[]),
    (499::BIGINT, 'Excelente profesor, es atento y explica muy bien la materia, ayuda al estudiante, lo único que no hace mucha practica en clase, pero en general lo recomiendo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2016-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'd2b231517672a7b9dd25725999e85e47b24e2f0d7c82af56bb924e4f5f3cc885'::TEXT, ARRAY[1041]::BIGINT[]),
    (499::BIGINT, 'Califica con forme a como explica las clases, algunas clases son aburridas pero es un muy buen profesor, excelente para pasar el curso a la primera.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2016-06-18T00:00:00+00:00'::TIMESTAMPTZ, '2a895bb4927655586997a14429ff6134076b6d96d9361564a46bf4f84df57ccc'::TEXT, ARRAY[935]::BIGINT[]),
    (499::BIGINT, 'Excelente Profesor, se le entiende con claridad y deja tareas, en lugar de hacer quices. Recomendado'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-06T00:00:00+00:00'::TIMESTAMPTZ, '94f8b37891d61a9f2dccc8885dbfc52267ac80591ba0999de7cdd02d110488d0'::TEXT, ARRAY[935]::BIGINT[]),
    (499::BIGINT, 'Va volando, pero es excelente. Sube las clases al tec digital para que uno no tenga que copiar. Muy buen profe.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-10T00:00:00+00:00'::TIMESTAMPTZ, 'b9e59a033233e610e0b33decea95248b3f28e91670c114eccae7c5200ce2570d'::TEXT, ARRAY[935]::BIGINT[]),
    (499::BIGINT, 'Quices medio rudos pero excelente profesor.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-01T00:00:00+00:00'::TIMESTAMPTZ, '456453aecfe8ce51d245e985778b51f188283359585ebe15a2f0190e6dd7c679'::TEXT, ARRAY[923]::BIGINT[]),
    (499::BIGINT, 'Es un excelente prof...'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-01T00:00:00+00:00'::TIMESTAMPTZ, '17c881120a3d986de4bb0d7914fbe1886db65b5fdd08885fefbda0721188c435'::TEXT, ARRAY[935]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
